import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.1C62pOns.js";const o="/pro-agent-hub-installer/capturas/en/login.png",r="/pro-agent-hub-installer/capturas/en/layout.png",i="/pro-agent-hub-installer/capturas/en/dashboard.png",f=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/primeiros-passos.md","filePath":"en/interface/primeiros-passos.md","lastUpdated":1791313012000}'),h={name:"en/interface/primeiros-passos.md"};function l(p,e,d,u,g,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p><img src="'+o+'" alt="login"></p><p>Access is by e-mail and password. On a fresh install, the initial user is created by the installer — its password is in the output of <code>install.sh</code>.</p><p><strong>Forgot my password</strong> sends a link by e-mail, so it only works once SMTP is configured in <a href="/pro-agent-hub-installer/en/interface/administracao#settings">Settings</a>. On a new install, before that, password recovery has no way out.</p><p><strong>Create account</strong> registers a user with no group at all. They sign in and see almost nothing — which is the correct behaviour: access is granted by a master, by linking the user to a group.</p><h2 id="the-menu" tabindex="-1">The menu <a class="header-anchor" href="#the-menu" aria-label="Permalink to &quot;The menu&quot;">​</a></h2><p><img src="'+r+'" alt="layout"></p><p>The side menu is split by subject: <strong>Main</strong> (day-to-day), <strong>AI configuration</strong> (what feeds the agents), <strong>Integrations</strong> and <strong>Administration</strong>. The last three only appear for master users.</p><p>It can be collapsed to a strip of icons; hovering brings the submenu up as an overlay. The search box at the top filters menu items by name — useful once an install has many Apps.</p><p><strong>Your Apps appear in the menu</strong>, right below Main, as items of their own — not inside a screen that lists them. To the people using it, &quot;Survey Form&quot; is a menu item like any other, not &quot;an App inside the App Builder&quot;.</p><h2 id="the-dashboard" tabindex="-1">The dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The dashboard&quot;">​</a></h2><p><img src="'+i+'" alt="dashboard"></p><p>The month&#39;s AI usage at the top — tokens, cost, the budget of the model closest to its limit and the top model —, the platform counters just below, and the charts: tokens per day over the last 30 days (the day&#39;s cost shows on hover), tokens per model and per source (chat or workflow) this month, and workflow runs by status. The previous month is spelled out, not shown as a percentage: halfway through a month, a % comparison would always look like a drop.</p><p>It is a summary, not an operations tool: to follow a workflow that is running, the screen is <a href="/pro-agent-hub-installer/en/interface/workflows#executions">Executions</a>; for usage and cost in detail, it is <a href="/pro-agent-hub-installer/en/interface/administracao#token-usage">Token usage</a>.</p><h2 id="theme-and-language" tabindex="-1">Theme and language <a class="header-anchor" href="#theme-and-language" aria-label="Permalink to &quot;Theme and language&quot;">​</a></h2><p>At the foot of the menu sit the theme switch (light/dark) and the language picker. The platform speaks Portuguese, English and Spanish; the choice is per user and survives between sessions.</p>',17)])])}const b=t(h,[["render",l]]);export{f as __pageData,b as default};
